#include <cstdio>
#include <vector>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    int slow = 0;
    for (int fast = 0; fast < n; ++fast) {
        if (a[fast] != 0) a[slow++] = a[fast];
    }
    while (slow < n) a[slow++] = 0;

    for (int i = 0; i < n; ++i) {
        if (i) printf(" ");
        printf("%lld", a[i]);
    }
    printf("\n");
    return 0;
}
